// Good code: Proper use of Java API with input validation and sanitization
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.util.regex.Pattern;

public class SecureServlet extends HttpServlet {
    private static final Pattern VALID_INPUT_PATTERN = Pattern.compile("^[a-zA-Z0-9_\\-\\s]+$");

    protected void doGet(HttpServletRequest request, HttpServletResponse response) {
        // Validate input before processing
        String userInput = request.getParameter("input");
        if (userInput == null || !VALID_INPUT_PATTERN.matcher(userInput).matches()) {
            response.setStatus(HttpServletResponse.SC_BAD_REQUEST);
            response.getWriter().println("Invalid input. Please enter a valid string.");
            return;
        }

        // Sanitize input to prevent XSS
        String sanitizedInput = userInput.replaceAll("<", "&lt;").replaceAll(">", "&gt;");
        response.getWriter().println("Received and processed: " + sanitizedInput);
    }
}
